const shortId = alertUUID.substring(0, 8);

return [{
  json: {
    // 原始告警数据
    alertData: alertData,

    // 格式化为可读 JSON（给大模型看）
    formattedAlert: JSON.stringify(alertData, null, 2),

    // 辅助字段（给 prompt 模板用）- 使用正确的字段
    alert_uuid: alertUUID,                           // ← 真正的告警UUID
