━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
生成时间：${timestamp}

【告警摘要】
主ID: ${reportData.alert_summary?.alert_uuid || 'N/A'}
短ID: ${reportData.alert_summary?.short_id || 'N/A'}
实例ID: ${reportData.alert_summary?.instance_id || 'N/A'}
时间: ${reportData.alert_summary?.timestamp_bjt || 'N/A'}
主机: ${reportData.alert_summary?.host || 'N/A'}
规则: ${reportData.alert_summary?.rule || 'N/A'}
严重度: ${reportData.alert_summary?.severity || 'N/A'}
Kibana: ${reportData.alert_summary?.kibana_url || 'N/A'}

【执行摘要】
${reportData.executive_summary || '无'}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Newflow ML 安全监控系统
此报告由 AI 安全分析引擎自动生成
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
`;

return [{
  json: {
    emailSubject: `🚨 威胁深度调查报告 · ${timestamp}`,
    emailBodyHtml: htmlEmail,
    emailBodyText: textEmail,
    timestamp: timestamp,
    reportLength: reportHtml.length
  }
}];

// JSON → HTML 转换器（替换原来的 Markdown转HTML 节点）
const inputData = $input.first().json;

// 获取 AI 输出 - 支持多种路径
let outputText = '';
if (inputData.response?.generations?.[0]?.[0]?.text) {
  // 兼容原始大模型返回格式
  outputText = inputData.response.generations[0][0].text;
} else {
  outputText = inputData.output || inputData.text || inputData.response || '';
}

console.log('原始输出长度:', outputText.length);
console.log('输出开头:', outputText.substring(0, 100));

// 清理可能的 Markdown 代码块标记
outputText = outputText.trim();
if (outputText.startsWith('```json')) {
  outputText = outputText.replace(/^```json\s*\n/, '').replace(/\n```\s*$/, '');
} else if (outputText.startsWith('```')) {
  outputText = outputText.replace(/^```\s*\n/, '').replace(/\n```\s*$/, '');
}

// 解析 JSON - 尝试修复截断的 JSON
let reportData;
try {
  reportData = JSON.parse(outputText);
  console.log('JSON 解析成功');
} catch (error) {
  console.error('JSON 解析失败:', error.message);
  console.log('尝试修复截断的 JSON...');

  // 尝试修复截断的 JSON - 找到最后一个完整的对象/数组
  let fixedText = outputText;

  // 移除最后可能不完整的行
  const lines = fixedText.split('\n');
  while (lines.length > 0) {
    fixedText = lines.join('\n');

    // 尝试闭合 JSON
    let testText = fixedText;
    const openBraces = (testText.match(/{/g) || []).length;
    const closeBraces = (testText.match(/}/g) || []).length;
    const openBrackets = (testText.match(/\[/g) || []).length;
    const closeBrackets = (testText.match(/]/g) || []).length;

    // 添加缺失的闭合符号
    for (let i = 0; i < openBrackets - closeBrackets; i++) testText += ']';
    for (let i = 0; i < openBraces - closeBraces; i++) testText += '}';

    try {
      reportData = JSON.parse(testText);
      console.log('JSON 修复成功!');
      break;
    } catch (e) {
      lines.pop();
    }
  }

  if (!reportData) {
    return [{
      json: {
        htmlContent: `<div class="error">
          <h2>⚠️ 报告解析失败</h2>
          <p>AI 返回的内容不完整或格式错误</p>
          <p><strong>可能原因:</strong> 大模型响应被截断(token 限制: 2048)</p>
          <p><strong>建议:</strong> 增加大模型的 max_tokens 参数至 4096 或更高</p>
          <details>
            <summary>查看原始输出 (前 1000 字符)</summary>
            <pre style="background:#f5f5f5;padding:12px;border-radius:6px;overflow:auto;max-height:400px;">${outputText.substring(0, 1000)}${outputText.length > 1000 ? '\n\n... (' + (outputText.length - 1000) + ' 字符被截断)' : ''}</pre>
          </details>
        </div>`,
        hasError: true,
        originalOutput: outputText
      }
    }];
  }
}

// 转义 HTML 字符
function escapeHtml(text) {
  if (!text) return '';
  const map = {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'};
  return String(text).replace(/[&<>"']/g, m => map[m]);
}

// 生成 HTML
const html = `
<h3>告警摘要</h3>
<div class="info-grid">
