        <td>${escapeHtml(row.action)}</td>
        <td>${escapeHtml(row.evidence)}</td>
      </tr>
    `).join('')}
  </tbody>
</table>

<h3>MITRE ATT&CK 技术</h3>
<ul class="mitre-list">
  ${(reportData.mitre_attack || []).map(item => `
    <li>
      <strong>${escapeHtml(item.tid)} ${escapeHtml(item.name)}:</strong>
      ${escapeHtml(item.description)}
    </li>
  `).join('')}
</ul>

<h3>影响范围</h3>
<ul class="impact-list">
  <li><strong>受影响主机:</strong> ${escapeHtml(reportData.impact?.affected_hosts || '0')}台</li>
  <li><strong>涉及用户:</strong> ${(reportData.impact?.users || []).map(u => escapeHtml(u)).join(', ') || '无'}</li>
  <li><strong>外部连接:</strong> ${escapeHtml(reportData.impact?.external_connections || '否')}${reportData.impact?.external_details ? ' → ' + escapeHtml(reportData.impact.external_details) : ''}</li>
