    <ul>
      ${(reportData.threat_score?.breakdown || []).map(item => `
        <li>${escapeHtml(item.factor)}: <span class="score-value">+${item.score}</span></li>
      `).join('')}
    </ul>
  </div>
</div>

<h3>处置建议</h3>
<div class="recommendations">
  <div class="rec-level">级别: <strong>${escapeHtml(reportData.recommendations?.level || 'N/A')}</strong></div>

