<hr class="heavy">

<div class="metadata">
  <p><strong>生成时间:</strong> ${escapeHtml(reportData.metadata?.generated_time || new Date().toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' }))}</p>
  <p><strong>查询次数:</strong> ${reportData.metadata?.query_count || (reportData.investigation_queries || []).length}次</p>
  <p><strong>报告编号:</strong> ${escapeHtml(reportData.alert_summary?.short_id || 'N/A')}</p>
